package org.diy.watchrecorder;

import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import java.io.*;import org.json.*;import java.util.concurrent.*;import org.diy.lifecore.LocalSecurity;

/** Synthetic files and emulator microphone only. No production fault injection. */
final class PowerTests {
    private static int checks;
    private static void check(boolean condition,String message)throws Exception{if(!condition)throw new IOException(message);checks++;}
    static int run(Instrumentation test,Context c)throws Exception{
        checks=0;check(Build.HARDWARE.equals("ranchu"),"emulator only");check(RecordingService.SEGMENT_MS==600000,"ten-minute capture segments");
        check(WatchSyncJob.due(1800001,1,true),"automatic sync eligible at thirty minutes");check(!WatchSyncJob.due(1499999,1,true),"automatic sync suppressed inside twenty-five minute cooldown");check(WatchSyncJob.due(1500001,1,true),"five-minute scheduler flex does not skip an entire thirty-minute batch");check(WatchSyncJob.due(1200001,1,true,600000),"WATCH 2 ten-minute platform flex permits early batch");check(!WatchSyncJob.due(1199999,1,true,600000),"WATCH 2 platform flex preserves twenty-minute minimum gap");check(WatchSyncJob.due(10,999999,false),"new boot permits sync");check(WatchSyncJob.due(10,-1,true),"initial sync eligible");
        SharedPreferences link=WatchLink.prefs(c);String oldToken=link.getString("token",null),oldPeer=link.getString("bluetooth_address",null);JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);
        try{link.edit().putString("token",LocalSecurity.seal("synthetic-power-token")).putString("bluetooth_address","00:11:22:33:44:55").putLong("attempt_elapsed",SystemClock.elapsedRealtime()).putInt("attempt_boot",WatchSyncJob.boot(c)).commit();jobs.cancel(WatchSyncJob.ID);WatchSyncJob.schedule(c);JobInfo first=jobs.getPendingJob(WatchSyncJob.ID);check(first!=null&&first.getIntervalMillis()==1800000&&first.isPersisted(),"one persisted thirty-minute job");long scheduled=first.getExtras().getLong("planned_at_elapsed_ms");Thread.sleep(30);WatchSyncJob.schedule(c);check(jobs.getPendingJob(WatchSyncJob.ID).getExtras().getLong("planned_at_elapsed_ms")==scheduled,"saving segments does not postpone scheduled batch");check(jobs.getPendingJob(WatchSyncJob.ID).getInitialBackoffMillis()==1800000,"retry backoff does not create minute polling");}
        finally{jobs.cancel(WatchSyncJob.ID);SharedPreferences.Editor restore=link.edit();if(oldToken==null)restore.remove("token");else restore.putString("token",oldToken);if(oldPeer==null)restore.remove("bluetooth_address");else restore.putString("bluetooth_address",oldPeer);restore.commit();}
        check(ContextRecorder.heartDelay(600001,1,900000)==300000,"fifteen-minute heart sample is not restarted at ten-minute boundary");check(ContextRecorder.heartDelay(900001,1,900000)==0,"due heart sample runs immediately");check(ContextRecorder.heartDelay(100,0,900000)==0,"first heart sample immediate");
        File dir=new File(c.getFilesDir(),"recordings");dir.mkdirs();File audio=new File(dir,"power-digest.m4a"),side=new File(audio.getPath()+".json");
        try{try(FileOutputStream out=new FileOutputStream(audio)){out.write(new byte[]{1,2,3,4});}try(FileOutputStream out=new FileOutputStream(side)){out.write(new JSONObject().put("started_at_epoch_ms",System.currentTimeMillis()).toString().getBytes("UTF-8"));}FinalizedDigest.forget(c,audio);long before=FinalizedDigest.bytesHashed;String sha=FinalizedDigest.get(c,audio);check(FinalizedDigest.bytesHashed-before==4,"first final file hashed once");check(FinalizedDigest.get(c,audio).equals(sha),"cache retains exact digest");ArchivePolicy.report(c,new JSONArray());long cached=FinalizedDigest.bytesHashed;ArchivePolicy.report(c,new JSONArray());ArchivePolicy.report(c,new JSONArray());check(FinalizedDigest.bytesHashed==cached,"repeated inventory does not reread audio");
            long stamp=audio.lastModified();try(RandomAccessFile edit=new RandomAccessFile(audio,"rw")){edit.writeByte(9);}check(audio.setLastModified(stamp),"tamper fixture preserves metadata");JSONArray ack=ArchivePolicy.apply(c,new JSONObject().put("commands",new JSONArray().put(new JSONObject().put("id","power-delete").put("name",audio.getName()).put("sha",sha))));check(audio.exists()&&ack.getJSONObject(0).getString("status").equals("mismatch"),"delete rehashes bytes despite matching cached metadata");check(audio.setLastModified(stamp+2000),"changed timestamp fixture");String changed=FinalizedDigest.get(c,audio);check(!changed.equals(sha)&&changed.equals(LocalSecurity.hash(audio)),"metadata change invalidates digest");try(FileOutputStream out=new FileOutputStream(audio,true)){out.write(5);}check(!FinalizedDigest.get(c,audio).equals(changed),"file size change invalidates digest");}
        finally{audio.delete();side.delete();FinalizedDigest.forget(c,audio);}
        sensorRotation(c);captureRotation(test,c);
        return checks;
    }
    private static boolean has(Handler h,Runnable r)throws Exception{return (boolean)Handler.class.getMethod("hasCallbacks",Runnable.class).invoke(h,r);}
    private static Object field(Object object,String name)throws Exception{java.lang.reflect.Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
    private static void sensorRotation(Context c)throws Exception{
        SharedPreferences prefs=c.getSharedPreferences("capture-policy",0);String old=prefs.getString("json","{}");prefs.edit().putString("json",new JSONObject().put("revision",450).put("heart",true).put("heart_interval_minutes",15).put("pressure",true).put("light",true).toString()).commit();
        HandlerThread thread=new HandlerThread("power-sensors");thread.start();Handler handler=new Handler(thread.getLooper());Throwable[] error={null};CountDownLatch done=new CountDownLatch(1);ContextRecorder[] recorder={null};long[] heartStart={0};File first=new File(c.getCacheDir(),"power-a.m4a.part"),next=new File(c.getCacheDir(),"power-b.m4a.part"),last=new File(c.getCacheDir(),"power-c.m4a.part");
        handler.post(()->{try{recorder[0]=new ContextRecorder(c,handler,first);handler.postDelayed(()->{try{
            heartStart[0]=(long)field(recorder[0],"lastHeartStart");check(heartStart[0]>0,"heart sampler starts");recorder[0].finishOutput();recorder[0].openOutput(next);check((long)field(recorder[0],"lastHeartStart")==heartStart[0],"output rotation does not immediately resample heart");check(has(handler,(Runnable)field(recorder[0],"heartWindow")),"heart timer survives segment rotation");
            // A settings change reschedules from the previous sample rather than from file start.
            prefs.edit().putString("json",new JSONObject().put("revision",451).put("heart",true).put("heart_interval_minutes",5).toString()).commit();recorder[0].finishOutput();recorder[0].openOutput(last);check((long)field(recorder[0],"lastHeartStart")==heartStart[0],"interval policy change retains previous sample time");recorder[0].close();check(!has(handler,(Runnable)field(recorder[0],"heartWindow"))&&!has(handler,(Runnable)field(recorder[0],"everyMinute")),"pause removes sensor callbacks");done.countDown();
        }catch(Throwable e){error[0]=e;try{recorder[0].close();}catch(Exception ignored){}done.countDown();}},3500);}catch(Throwable e){error[0]=e;done.countDown();}});
        try{check(done.await(12,TimeUnit.SECONDS),"sensor rotation finishes");if(error[0]!=null)throw new IOException(error[0]);for(String name:new String[]{"power-a","power-b","power-c"}){File output=new File(c.getCacheDir(),name+".context.jsonl");check(output.isFile()&&new String(java.nio.file.Files.readAllBytes(output.toPath()),"UTF-8").contains("capabilities"),"each segment gets finalized sensor metadata");}}
        finally{prefs.edit().putString("json",old).commit();handler.post(()->{try{if(recorder[0]!=null)recorder[0].close();}catch(Exception ignored){}});thread.quitSafely();for(String name:new String[]{"power-a","power-b","power-c"}){new File(c.getCacheDir(),name+".context.jsonl").delete();new File(c.getCacheDir(),name+".context.jsonl.part").delete();}}
    }
    private static void captureRotation(Instrumentation test,Context c)throws Exception{
        c.getSharedPreferences("wake-word",0).edit().putBoolean("enabled",false).commit();c.getSharedPreferences("capture-policy",0).edit().putString("json",new JSONObject().put("revision",452).put("heart",true).put("heart_interval_minutes",15).toString()).commit();
        Activity activity=test.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));c.startForegroundService(new Intent(c,RecordingService.class).setAction(RecordingService.START));Thread.sleep(1800);
        Object[] active={null};test.runOnMainSync(()->{try{Class<?> cls=Class.forName("android.app.ActivityThread");java.lang.reflect.Method current=cls.getDeclaredMethod("currentActivityThread");current.setAccessible(true);Object at=current.invoke(null);java.lang.reflect.Field services=cls.getDeclaredField("mServices");services.setAccessible(true);for(Object s:((java.util.Map<?,?>)services.get(at)).values())if(s instanceof RecordingService)active[0]=s;}catch(Exception e){throw new RuntimeException(e);}});
        check(active[0]!=null,"real capture service starts");RecordingService service=(RecordingService)active[0];Object observation=field(service,"observations");long last=(long)field(observation,"lastHeartStart");File pending=(File)field(service,"pending");Handler worker=(Handler)field(service,"worker");CountDownLatch rotated=new CountDownLatch(1);Throwable[] error={null};
        worker.post(()->{try{((Runnable)field(service,"rotate")).run();}catch(Throwable e){error[0]=e;}finally{rotated.countDown();}});check(rotated.await(8,TimeUnit.SECONDS),"rotation completes");if(error[0]!=null)throw new IOException(error[0]);Thread.sleep(500);
        check(field(service,"observations")==observation,"real recording rotation keeps sensor owner");check((long)field(observation,"lastHeartStart")==last,"real recording rotation preserves heart cadence");File saved=new File(pending.getPath().replace(".part",""));check(saved.isFile()&&new File(saved.getPath()+".json").isFile(),"first audio and metadata saved");android.media.MediaMetadataRetriever media=new android.media.MediaMetadataRetriever();try{media.setDataSource(saved.getPath());check(Long.parseLong(media.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION))>0,"saved rotated AAC is playable");}finally{media.release();}
        c.startService(new Intent(c,RecordingService.class).setAction(RecordingService.PAUSE));Thread.sleep(700);check(CaptureIntent.mode(c).equals(CaptureIntent.PAUSED)&&!has(worker,(Runnable)field(observation,"heartWindow")),"pause stops sampler and keeps explicit paused intent");c.startService(new Intent(c,RecordingService.class).setAction(RecordingService.STOP));Thread.sleep(500);test.runOnMainSync(activity::finish);
    }
}
